'\''1i /* rewrite the pattern to match case insensitively without REG_ICASE,
   which cannot be enabled per pattern in a highlight set */
static void vi_icasepat(sbuf *d, char *s)
{
	int cls = 0, c, e;
	while (*s) {
		c = (unsigned char)*s;
		if (c == '\''\\'\'' && s[1]) {
			sbuf_mem(d, s, 2)
			s += 2;
			continue;
		}
		if (!cls && c == '\''['\'') {
			sbuf_chr(d, *s++)
			cls = 1;
			if (*s == '\''^'\'')
				sbuf_chr(d, *s++)
			if (*s == '\'']'\'')
				sbuf_chr(d, *s++)
			continue;
		}
		if (c > 127 || !isalpha(c)) {
			cls = cls && c != '\'']'\'';
			sbuf_chr(d, *s++)
			continue;
		}
		c = islower(c) ? toupper(c) : tolower(c);
		if (!cls)
			sbuf_chr(d, '\''['\'')
		if (cls && s[1] == '\''-'\'' && isalpha((unsigned char)s[2])) {
			e = (unsigned char)s[2];
			e = islower(e) ? toupper(e) : tolower(e);
			sbuf_mem(d, s, 3)
			sbuf_chr(d, c)
			sbuf_chr(d, '\''-'\'')
			sbuf_chr(d, e)
			s += 3;
		} else {
			sbuf_chr(d, *s++)
			sbuf_chr(d, c)
		}
		if (!cls)
			sbuf_chr(d, '\'']'\'')
	}
	sbufn_null(d)
}

/* read the search keyword, previewing matches as it is typed */
static char *vi_isearch(int cmd, int *ret, int *mlen)
{
	int key, row, off, len, drawn = 0, dir = cmd == '\''/'\'' ? +2 : -2;
	int orow = xrow, ooff = xoff, otop = xtop, oleft = xleft;
	int hl = syn_findhl(1), odir = xkwddir;
	char *ohl = hl >= 0 ? hls[hl].pat : NULL;
	char *okwd = ex_regget('\''/'\'') ? uc_dup(ex_regget('\''/'\'')->s) : NULL;
	ins_state is;
	ins_init(is)
	sbuf_smake(sb, xcols)
	sbuf_smake(hlb, xcols)
	sbuf_chr(sb, cmd)
	*mlen = sb->s_n;
	while (1) {
		term_pos(xrows, 0);
		syn_setft(vs_ft);
		len = sb->s_n;
		key = led_prompt(sb, NULL, &xkmap, &is, *mlen, 2);
		syn_setft(xb_ft);
		sbuf_null(sb)
		/* an erase key that removed nothing ends an empty prompt */
		if (key == '\''\n'\'' || TK_INT(key) || xquit
				|| (key == 127 && sb->s_n == len))
			break;
		if (!xled || (sb->s_n == *mlen && !drawn))
			continue;
		xrow = orow, xoff = ooff, xtop = otop;
		if (sb->s_n > *mlen) {
			row = orow, off = ooff;
			ex_krsset(sb->s + *mlen, dir);
			if (xkwdrs && xgrp < xkwdrs->nsubc && lbuf_len(xb)
					&& !lbuf_search(xb, xkwdrs, xkwddir, 0,
						lbuf_len(xb), xkwddir, 1, &row, &off)) {
				xrow = row, xoff = off;
				if (xrow < xtop || xrow >= xtop + xrows)
					xtop = MAX(0, xrow - xrows / 2);
			}
		}
		if (hl >= 0) {
			sbuf_cut(hlb, 0)
			if (sb->s_n > *mlen) {
				if (xic)
					vi_icasepat(hlb, sb->s + *mlen);
				else
					sbufn_str(hlb, sb->s + *mlen)
			}
			syn_reloadft(syn_addhl(sb->s_n > *mlen ? hlb->s : NULL, 1), 0);
		}
		term_record = 1;
		vi_drawagain(xtop);
		term_commit();
		drawn = 1;
	}
	if (hl >= 0 && drawn)
		syn_reloadft(syn_addhl(ohl, 1), 0);
	*ret = key == '\''\n'\'';
	if (*ret && sb->s_n > *mlen) {
		lbuf_dedup(tempbufs[0].lb, sb->s + *mlen, sb->s_n - *mlen)
		temp_pos(0, -1, 0, 0);
		temp_write(0, sb->s + *mlen);
	} else if (okwd)	/* the preview must not alter the last keyword */
		ex_krsset(okwd, *ret ? dir : odir * 2);
	else if (xkwdrs) {
		rset_free(xkwdrs);
		xkwdrs = NULL;
	}
	free(okwd);
	free(hlb->s);
	xrow = orow, xoff = ooff, xtop = otop, xleft = oleft;
	vi_mod |= drawn;
	return sb->s;
}

