+		c = (unsigned char)*s;
+		if (c == '\\' && s[1]) {
+			sbuf_mem(d, s, 2)
+			s += 2;
+			continue;
+		}
+		if (!cls && c == '[') {
+			sbuf_chr(d, *s++)
+			cls = 1;
+			if (*s == '^')
+				sbuf_chr(d, *s++)
+			if (*s == ']')
+				sbuf_chr(d, *s++)
+			continue;
+		}
+		if (c > 127 || !isalpha(c)) {
+			cls = cls && c != ']';
