+			sbuf_chr(d, c)
+			sbuf_chr(d, '-')
+			sbuf_chr(d, e)
+			s += 3;
+		} else {
+			sbuf_chr(d, *s++)
+			sbuf_chr(d, c)
+		}
+		if (!cls)
+			sbuf_chr(d, ']')
+	}
+	sbufn_null(d)
+}
